    padding-block-start: var(--ak-c-dialog__body--PaddingBlockStart);
    padding-inline-end: var(--ak-c-dialog__body--PaddingInlineEnd);
    padding-inline-start: var(--ak-c-dialog__body--PaddingInlineStart);
