    --ak-c-dialog--TransitionDuration--Opacity: 100ms;
    --ak-c-dialog--TransitionDuration--Backdrop: 100ms;
    --ak-c-dialog--TransitionDuration--Overlay: 50ms;
    --ak-c-dialog--TransitionDuration--Display: 50ms;
}

/* #endregion */

/* #region Dialog */

.ak-c-dialog {
    overscroll-behavior: none;
